<?php
use AISkillsHub\Core\Learning\SubscriptionFrontend as SubscriptionsView;
use AISkillsHub\Core\Accounts\Frontend as AccountView;
use AISkillsHub\Core\Frontend\{Router, View};
defined( 'ABSPATH' ) || exit;
$c = SubscriptionsView::context(); $locale = $c['locale']; $route = $c['route'];
$t = static fn( string $zh, string $en ): string => SubscriptionsView::t( $zh, $en );
$url = static fn( string $r = 'newsletter' ): string => SubscriptionsView::url( $r, $locale );
$public = static fn( string $r ): string => Router::url( $r, array(), $locale );
$preferences = is_array( $c['preferences'] ?? null ) ? $c['preferences'] : array();
$values = $c['values'] ?: $preferences;
$stateLabels = array( 'none' => $t( '尚未订阅', 'Not subscribed' ), 'pending' => $t( '等待邮箱确认', 'Awaiting email confirmation' ), 'active' => $t( '已确认订阅', 'Subscription confirmed' ), 'paused' => $t( '订阅已暂停', 'Subscription paused' ), 'unsubscribed' => $t( '已取消订阅', 'Unsubscribed' ), 'bounced' => $t( '因退信暂停', 'Suppressed after a bounce' ), 'needs_confirmation' => $t( '需要重新验证并确认', 'Verification and confirmation required' ), 'expired' => $t( '确认已过期', 'Confirmation expired' ) );
$title = match ( $route ) { 'confirm' => $t( '确认邮件订阅', 'Confirm email subscription' ), 'unsubscribe' => $t( '取消邮件订阅', 'Unsubscribe from emails' ), default => $t( '邮件订阅', 'Email subscriptions' ) };
$open = static function ( string $action ) use ( $url, $route ): void { echo '<form method="post" action="' . esc_url( $url( $route ) ) . '" class="account-form" data-account-form>' . SubscriptionsView::fields( $action ); };
$button = static function ( string $text, bool $disabled = false, bool $danger = false ) use ( $t ): void { echo '<button type="submit" class="account-button ' . ( $danger ? 'account-button-danger' : 'account-button-primary' ) . '" data-pending-label="' . esc_attr( $t( '正在处理…', 'Processing…' ) ) . '"' . ( $disabled ? ' disabled' : '' ) . '>' . esc_html( $text ) . '</button>'; };
$available = $c['availability'] ?? array(); $canRequest = ! empty( $available['enabled'] ) && empty( $available['paused'] ) && ! empty( $available['mail_ready'] );
?>
<!doctype html>
<html lang="<?php echo esc_attr( 'zh_CN' === $locale ? 'zh-CN' : 'en' ); ?>">
<head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#F9FAFB"><?php wp_head(); ?></head>
<body <?php body_class( 'aish-account-site' ); ?>>
<?php wp_body_open(); ?><a class="account-skip" href="#newsletter-main"><?php echo esc_html( $t( '跳到主要内容', 'Skip to main content' ) ); ?></a>
<header class="account-site-header"><div class="account-container account-header-inner"><a class="account-brand" href="<?php echo esc_url( $public( 'home' ) ); ?>"><span class="account-brand-symbol" aria-hidden="true"><?php echo View::icon( 'layers' ); ?></span><span>AI Skills <span class="account-muted">Hub</span></span></a><nav class="account-language" aria-label="<?php echo esc_attr( $t( '界面语言', 'Interface language' ) ); ?>"><a href="<?php echo esc_url( SubscriptionsView::url( $route, 'zh_CN' ) ); ?>" lang="zh-CN" <?php echo 'zh_CN' === $locale ? 'aria-current="true"' : ''; ?>>中</a><span aria-hidden="true">/</span><a href="<?php echo esc_url( SubscriptionsView::url( $route, 'en_US' ) ); ?>" lang="en" <?php echo 'en_US' === $locale ? 'aria-current="true"' : ''; ?>>EN</a></nav></div></header>
<main id="newsletter-main" class="account-main" tabindex="-1"><div class="account-container"><div class="account-auth-wrap"><a class="account-back" href="<?php echo esc_url( $public( 'skills' ) ); ?>">← <?php echo esc_html( $t( '继续探索资源', 'Continue exploring' ) ); ?></a><section class="account-panel account-auth-panel"><header class="account-page-heading"><h1><?php echo esc_html( $title ); ?></h1><p><?php echo esc_html( $t( '自愿选择你希望收到的内容。订阅不影响免费浏览、收藏、评价或投稿。', 'Choose the emails you want. Subscribing is optional and does not affect free browsing, favorites, reviews or submissions.' ) ); ?></p></header>
<?php if ( ! empty( $c['error'] ) ) : ?>
<div class="account-notice account-error" id="subscription-feedback" role="alert" tabindex="-1" data-account-feedback><p><?php echo esc_html( match ( $c['error'] ) { 'csrf' => $t( '表单已过期或无法验证，请重新加载后重试。', 'This form expired or could not be verified. Reload and try again.' ), 'invalid_input' => $t( '请选择邮件语言和至少一种内容，并明确勾选订阅同意。', 'Choose an email language and at least one topic, and explicitly agree to subscribe.' ), 'invalid_token' => $t( '链接无效、已使用或已失效。请使用最新邮件中的链接。', 'This link is invalid, used or expired. Use the link in your latest email.' ), 'rate_limited' => $t( '操作过于频繁，请稍后重试。', 'Too many requests. Please try again later.' ), 'forbidden', 'verification_required' => $t( '请先登录并验证当前账户邮箱。', 'Sign in and verify your current account email first.' ), 'conflict' => $t( '状态已发生变化，请刷新后检查再提交。', 'The state changed. Refresh and review it before submitting again.' ), default => $t( '暂时无法确认操作成功。请稍后重新检查订阅状态。', 'We could not confirm this operation. Check your subscription state again later.' ) } ); ?></p><a class="account-text-action" href="<?php echo esc_url( $url( $route ) ); ?>"><?php echo esc_html( $t( '重新加载', 'Reload page' ) ); ?></a></div>
<?php endif; ?>
<?php if ( ! empty( $c['message'] ) ) : ?><div class="account-notice" role="status" tabindex="-1" data-account-feedback><p><?php echo esc_html( match ( $c['message'] ) { 'confirmed' => $t( '邮件订阅已确认。你可以随时取消订阅。', 'Your email subscription is confirmed. You can unsubscribe at any time.' ), 'unsubscribed' => $t( '已取消营销邮件订阅。必要的账户安全邮件不受影响。', 'You have unsubscribed from marketing emails. Essential account security emails are unaffected.' ), default => $t( '请求已处理。需要确认时，确认邮件会进入发送队列；请使用最新邮件中的链接。排队或传输受理不代表已送达。', 'Your request was processed. When confirmation is needed, a confirmation email is queued; use the latest link. Queueing or transport acceptance does not prove delivery.' ) } ); ?></p></div><?php endif; ?>
<?php if ( 'newsletter' !== $route ) : ?>
	<?php if ( 'confirm' === $route && empty( $c['eligible'] ) && empty( $c['message'] ) ) : ?>
		<p><?php echo esc_html( $t( '请登录申请订阅时使用的账户，并验证其当前邮箱后确认。链接只保留在本浏览器中，不会转移到其他账户。', 'Sign in with the account that requested this subscription and verify its current email before confirming. The link stays in this browser and cannot transfer a subscription to another account.' ) ); ?></p><a class="account-button account-button-primary" href="<?php echo esc_url( is_user_logged_in() ? AccountView::url( 'verify-email', $locale ) : AccountView::loginUrl( $url( 'confirm' ), $locale ) ); ?>"><?php echo esc_html( is_user_logged_in() ? $t( '查看邮箱验证', 'Check email verification' ) : $t( '登录后确认', 'Sign in to confirm' ) ); ?></a>
	<?php elseif ( ! empty( $c['credential'] ) && empty( $c['message'] ) ) : ?>
		<p><?php echo esc_html( 'confirm' === $route ? $t( '确认后只启用此次明确选择的邮件偏好，不会修改你的账户身份或订阅其他内容。', 'Confirm only the email choices in this request. This does not change your account identity or subscribe you to other topics.' ) : $t( '无需登录。确认取消后，不再派发这项订阅的营销邮件。已经交给邮件服务的邮件可能无法撤回。', 'No sign-in is required. Cancelling stops future dispatch for this subscription. Messages already accepted by a mail service may not be retractable.' ) ); ?></p>
		<?php $open( $route ); $button( 'confirm' === $route ? $t( '确认订阅', 'Confirm subscription' ) : $t( '取消订阅', 'Unsubscribe' ), false, 'unsubscribe' === $route ); echo '</form>'; ?>
	<?php elseif ( empty( $c['message'] ) ) : ?><p class="account-empty"><?php echo esc_html( $t( '请使用最新邮件中的有效链接。过期或已撤销的链接不能更改订阅。', 'Use a valid link from your latest email. Expired or revoked links cannot change a subscription.' ) ); ?></p><?php endif; ?>
	<a class="account-text-action" href="<?php echo esc_url( $url() ); ?>"><?php echo esc_html( $t( '查看订阅偏好', 'View subscription preferences' ) ); ?></a>
<?php elseif ( ! is_user_logged_in() ) : ?>
	<p><?php echo esc_html( $t( '邮件订阅面向已验证的注册用户。注册不会自动订阅；登录后你可以主动选择，并单独通过邮件确认。', 'Email subscriptions are available to verified registered users. Registration never opts you in. Sign in to choose topics and confirm separately by email.' ) ); ?></p><a class="account-button account-button-primary" href="<?php echo esc_url( AccountView::loginUrl( $url(), $locale ) ); ?>"><?php echo esc_html( $t( '登录后设置订阅', 'Sign in to choose emails' ) ); ?></a>
<?php elseif ( empty( $c['eligible'] ) ) : ?>
	<p><?php echo esc_html( $t( '请先验证当前账户邮箱。未完成验证或受限制的账户不能开启订阅。', 'Verify your current account email first. Unverified or restricted accounts cannot start subscriptions.' ) ); ?></p><a class="account-button account-button-primary" href="<?php echo esc_url( AccountView::url( 'verify-email', $locale ) ); ?>"><?php echo esc_html( $t( '查看邮箱验证', 'Check email verification' ) ); ?></a><p class="account-help"><?php echo esc_html( $t( '你仍可取消本账户的邮件订阅，无需先完成验证。', 'You can still cancel this account’s email subscription without completing verification first.' ) ); ?></p><?php $open( 'stop' ); $button( $t( '取消本账户的邮件订阅', 'Cancel this account’s emails' ), false, true ); echo '</form>'; ?>
<?php else : ?>
	<p class="account-help"><?php echo esc_html( $t( '当前账户邮箱：', 'Current account email: ' ) . AccountView::maskEmail( (string) wp_get_current_user()->user_email ) ); ?></p><p><strong><?php echo esc_html( $stateLabels[ $preferences['state'] ?? 'none' ] ?? $t( '状态待核实', 'State unavailable' ) ); ?></strong></p>
	<?php if ( ! $canRequest ) : ?><div class="account-notice"><p><?php echo esc_html( $t( '邮件订阅暂未开放或已暂停。你仍可以查看状态并取消现有订阅。', 'Email subscriptions are not available or are paused. You can still view your state and cancel an existing subscription.' ) ); ?></p></div><?php endif; ?>
	<?php $open( 'request' ); ?><input type="hidden" name="request_key" value="<?php echo esc_attr( bin2hex( random_bytes( 32 ) ) ); ?>">
	<div class="account-field"><label for="subscription-locale"><?php echo esc_html( $t( '邮件语言', 'Email language' ) ); ?></label><select id="subscription-locale" name="locale"><option value="zh_CN" <?php selected( $values['locale'] ?? $locale, 'zh_CN' ); ?>>简体中文</option><option value="en_US" <?php selected( $values['locale'] ?? $locale, 'en_US' ); ?>>English</option></select></div>
	<fieldset><legend class="account-strong"><?php echo esc_html( $t( '我希望收到', 'I would like to receive' ) ); ?></legend><label class="account-check"><input type="checkbox" name="weekly" value="1" <?php checked( ! empty( $values['weekly'] ) ); ?>><span><?php echo esc_html( $t( '每周精选：人工精选资源、教程和使用场景', 'Weekly picks: curated Skills, tutorials and use cases' ) ); ?></span></label><label class="account-check"><input type="checkbox" name="new_resources" value="1" <?php checked( ! empty( $values['new_resources'] ) ); ?>><span><?php echo esc_html( $t( '新资源汇总：已审核的新收录内容', 'New resource digests: newly added, reviewed content' ) ); ?></span></label></fieldset>
	<p class="account-help"><?php echo esc_html( $t( '修改语言或内容范围需重新通过邮件确认。未翻译内容不会伪装成所选语言发送。', 'Changes to language or topics require a new email confirmation. Untranslated content will not be presented as your selected language.' ) ); ?></p>
	<label class="account-check"><input type="checkbox" name="consent" value="1" required aria-describedby="subscription-consent-help"><span><?php echo esc_html( $t( '我自愿订阅以上内容，并同意向当前已验证邮箱发送确认邮件。', 'I voluntarily subscribe to these topics and agree to receive a confirmation email at my current verified address.' ) ); ?></span></label><p id="subscription-consent-help" class="account-help"><?php echo esc_html( $t( '你可以随时通过邮件中的退订入口或本页取消，不影响必要安全通知。', 'Unsubscribe at any time from an email or this page. Essential security notifications are separate.' ) ); ?></p>
	<?php $button( $t( '保存选择并申请邮件确认', 'Save choices and request confirmation' ), ! $canRequest ); echo '</form>'; ?>
	<?php if ( $preferences && ! in_array( $preferences['state'] ?? '', array( 'none', 'unsubscribed' ), true ) ) : ?><hr><?php $open( 'stop' ); $button( $t( '取消邮件订阅', 'Unsubscribe from emails' ), false, true ); echo '</form>'; ?><?php endif; ?>
	<p><a class="account-text-action" href="<?php echo esc_url( AccountView::url( 'settings', $locale ) ); ?>"><?php echo esc_html( $t( '返回账户设置', 'Back to account settings' ) ); ?></a></p>
<?php endif; ?>
</section></div></div></main><footer class="account-footer"><div class="account-container"><p>AI Skills Hub · <?php echo esc_html( $t( '免费探索，自主选择', 'Explore freely. Choose your preferences.' ) ); ?></p></div></footer><?php wp_footer(); ?></body></html>
